<template><div class="scenario-overview" v-loading="loading"><el-alert title="Local Demo prices and scenario data. Current business definitions and Open decisions are shown in the Business Relations tab." type="info" :closable="false" class="module-notice"/><template v-if="data"><div class="metrics-grid"><div v-for="metric in metrics" :key="metric.key" class="metric-card"><span>{{ metric.label }}</span><strong>{{ data[metric.key] }}</strong></div></div><section class="section-card"><h2 class="section-title">Scenario Users</h2><div class="section-body"><el-table :data="data.usersWithScenarios" row-key="id" border><el-table-column prop="name" label="User" min-width="180"/><el-table-column prop="scenario" label="Scenario" min-width="260"/><el-table-column prop="membership" label="Effective Base" min-width="150"/><el-table-column prop="aiCoachBalance" label="AI Coach Credits" width="150"/><el-table-column prop="contentBalance" label="Content Credits" width="145"/><el-table-column prop="balance" label="Historical Credits" width="145"/><el-table-column label="Actions" width="240"><template slot-scope="s"><el-button type="text" @click="$router.push('/commercialization/users/'+s.row.id)">View Rights</el-button><el-button type="text" @click="$router.push({path:'/commercialization/operations',query:{user:s.row.id}})">Run Flow</el-button><el-button type="text" @click="$router.push({path:'/app/home',query:{user:s.row.id}})">App</el-button></template></el-table-column></el-table></div></section><section class="section-card"><h2 class="section-title">Recent Credits Events</h2><div class="section-body"><records-table kind="ledger" :rows="data.recentLedger"/></div></section><p class="field-help">Quote validity: {{ data.policy.quoteMinutes }} minutes. Request reservation lease: {{ data.policy.reservationMinutes }} minutes. Demo payments and results use local adapters.</p></template><el-alert v-if="error" :title="error" type="error" :closable="false"/></div></template>
<script>
import {overview} from '@/api/commerce'
import RecordsTable from '@/components/Commerce/RecordsTable'
export default{components:{RecordsTable},data(){return{data:null,loading:false,error:'',metrics:[{key:'users',label:'Users'},{key:'paidMembers',label:'Active Paid Bases'},{key:'availableAiCredits',label:'AI Coach Credits'},{key:'availableContentCredits',label:'Content Credits'},{key:'availableCredits',label:'Historical Credits'},{key:'reservedCredits',label:'Historical Reservations'},{key:'pendingFulfillment',label:'Pending Fulfillment'},{key:'content',label:'Published Content'}]}},created(){this.load()},methods:{async load(){this.loading=true;try{this.data=await overview();this.error=''}catch(e){this.error=e.message}finally{this.loading=false}}}}
</script>
